p(y)\n# y = ln(P(1)/P(0))\n\ny = math.log(P_1954 / P_1953)\nprint(f\"Yield (continuous): {y}\")\n\n# Normalize by treating later observation as face value (at maturity)\n# At t=1 (FY1954): price = F (face value), so we're at maturity\n# At t=0 (FY1953): price = F * exp(-y * D) where D is Macaulay duration\n\n# From normalization: P(0)/P(1) = exp(-y * D)\n# D = -ln(P(0)/P(1))/y = -ln(4187/6207)/ln(6207/4187)\n\nD = -math.log(P_1953/P_1954) / y\n\nprint(f\"\\nMacaulay Duration (unrounded): {D}\")\nprint(f\"Duration to 4 decimal places: {D:.4f}\")\n\n# Verify with the interpretation:\n# If D = 1, at t=0 we're 1 year from maturity\n# At t=1 (maturity): price = 6207 (face value)\n# At t=0: price = 6207 * exp(-y * 1) = 6207 * exp(-0.3937) ≈ 4187 ✓\n\n# This confirms consistency\nprint(f\"\\nVerification: 6207 * exp(-{y:.4f} * 1) = {6207 * math.exp(-y):.4f}\")\nprint(f\"Should equal 4187\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
